import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = {
        ('IDM6', 'QWK15B'), ('EEN15', 'YWC15'), ('EEN15', 'TJO6'), 
        ('EEN15', 'JNYL10P'), ('PLL7', 'NCB6'), ('VHX1A', 'NMJD8'),
        ('TJO6', 'JNYL10P'), ('TJO6', 'NMJD8'), ('TJO6', 'YWC15'),
        ('EEN15', 'GDM6'), ('YWC15', 'JNYL10P'), ('KIE15', 'CDD15'),
        ('EEN15', 'MXC13'), ('JNYL10P', 'GDM6'), ('JSTE5', 'YSO11'),
        ('TJO6', 'GDM6'), ('PLL7', 'MXC13'), ('NMJD8', 'JNYL10P'),
        ('NMJD8', 'VDO6'), ('JSTE5', 'SAHW1')
    }

    # Build set of features to consider
    feature_ids = list(feats.ids)
    feature_set = set(feature_ids)

    # Remove one feature from each highly correlated pair
    to_remove = set()
    for a, b in correlated_pairs:
        if a in feature_set and b in feature_set:
            to_remove.add(b)  # Remove second feature in pair

    remaining_features = [fid for fid in feature_ids if fid not in to_remove]

    # Compute pairwise correlations among remaining features
    X = feats.x[:, [feats.column(fid) for fid in remaining_features]]
    corr_matrix = np.corrcoef(X.T)

    # Identify clusters of highly correlated features
    cluster_map = {}
    visited = set()

    for i, fid in enumerate(remaining_features):
        if fid in visited:
            continue
        cluster = set([fid])
        visited.add(fid)

        for j, other_fid in enumerate(remaining_features):
            if i != j and other_fid not in visited:
                if abs(corr_matrix[i, j]) >= 0.6:
                    cluster.add(other_fid)
                    visited.add(other_fid)

        for f in cluster:
            cluster_map[f] = tuple(sorted(cluster))

    # Group features by their clusters
    clusters = defaultdict(list)
    for f, c in cluster_map.items():
        clusters[c].append(f)

    # Select one representative from each cluster (highest mean_y1-mean_y0)
    representatives = []
    for cluster in clusters.values():
        # Find feature with highest effect size
        best_fid = max(cluster, key=lambda fid: abs(feats.y[feats.column(fid)]))
        representatives.append(best_fid)

    # Sort by effect size (descending)
    representatives.sort(key=lambda fid: abs(feats.y[feats.column(fid)]), reverse=True)

    # Select top features for drivers (at most MAX_DRIVERS)
    drivers = tuple(representatives[:MAX_DRIVERS])

    # If no strong drivers found, return empty design
    if len(drivers) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select all features with high correlation to drivers
    selected_columns = set()
    for driver in drivers:
        col_idx = feats.column(driver)
        selected_columns.add(driver)

        # Add features highly correlated with this driver
        for i, fid in enumerate(remaining_features):
            if i != col_idx:
                corr_val = corr_matrix[col_idx, i]
                if abs(corr_val) >= 0.4:
                    selected_columns.add(fid)

    # Create products between drivers
    products = []
    for i, d1 in enumerate(drivers):
        for j, d2 in enumerate(drivers):
            if i < j:
                products.append((d1, d2))

    # Return design
    return Design(
        drivers=drivers,
        columns=tuple(selected_columns),
        products=tuple(products),
        loadings={fid: 1.0 for fid in selected_columns}
    )
